mapper.select:
select r.*, u.username as userName from reservation r
left join user u on r.user_id = u.id

    
        and r.user_id = #{params.userId}
    
    
        and r.status = #{params.status}
    
    
        and r.start_time >= #{params.startDate}
    
    
        and r.start_time <= #{params.endDate}
    
    
        and r.floor_number = #{params.floorNumber}
    

order by r.start_time desc
